-- (97, 3-oct-2026) Also a RESEND in another photo: same date (any year) and amount within 10% of a receipt of
-- the same customer in 48 h (cerebro_comprobante_reenviado, 203) -> duplicate of that original (Bruce, 2-oct).
WITH prev AS (SELECT whatsapp_message_id AS wamid_previo FROM comprobantes_hashes WHERE hash_imagen = $1), ins AS (INSERT INTO comprobantes_hashes (hash_imagen, cliente_whatsapp, comp_id, whatsapp_message_id) SELECT $1, $2, NULLIF($3,''), NULLIF($5,'') WHERE $4 = 'comprobante' AND $1 IS NOT NULL ON CONFLICT (hash_imagen) DO NOTHING RETURNING 1), dup AS (SELECT ($4 = 'comprobante' AND EXISTS(SELECT 1 FROM prev) AND NOT (cerebro_config_get('dedup_por_wamid') = 'on' AND NULLIF($5,'') IS NOT NULL AND EXISTS(SELECT 1 FROM prev WHERE prev.wamid_previo = NULLIF($5,'')))) AS duplicado), reenvio AS (SELECT cerebro_comprobante_reenviado($2, NULLIF($6,''), NULLIF($7,'')::numeric, NULLIF($8,'')) AS comp_original WHERE $4 = 'comprobante' AND NOT (SELECT duplicado FROM dup)), mark AS (SELECT cerebro_marcar_reenvio_comprobante($1, NULLIF($5,'')) AS marcado WHERE (SELECT duplicado FROM dup)) SELECT ((SELECT duplicado FROM dup) OR (SELECT comp_original FROM reenvio) IS NOT NULL) AS duplicado, (SELECT marcado FROM mark) AS marcado, (SELECT comp_original FROM reenvio) AS comp_id_original;

