const base=$('Armar snapshot').first().json;let vision=[],dedup=[];try{vision=$('Parsear vision').all().map(i=>i.json)}catch(e){}try{dedup=$('Dedup comprobantes').all().map(i=>i.json)}catch(e){}const texto=(base.texto_completo??'').toString();
// Deteccion automatica SOLO sobre texto ESCRITO: las lineas de notas de voz se excluyen.
// Regla 11 del agente: numeros DICTADOS se confirman en conversacion, nunca se registran solos.
const texto_escrito=texto.split('\n').filter(l=>{const t=l.trim();return !t.startsWith('[Nota de voz')&&!t.startsWith('[El cliente mando')}).join('\n');
const tarjetas=[],celulares=[],numeros_no_reconocidos=[];const add=(a,v)=>{if(v&&!a.includes(v))a.push(v)};
// Celular cubano: 8 digitos que empiezan por 5, o por 63 (lineas nuevas de ETECSA desde el 30-dic-2023).
const esMovilCU=d=>/^(5\d{7}|63\d{6})$/.test(d);
// 16 EXACTOS O 8 EXACTOS, NADA MAS (fase 1B).
// Hasta hoy un run de >=24 digitos que empezaba por 5 se PARTIA en celular y
// tarjeta, y un run de mas de 16 se RECORTABA a los 16 primeros. Las dos reglas
// FABRICAN un dato financiero a partir de algo que el cliente escribio mal: si
// pega dos numeros seguidos, o le sobra un digito, se registraba una tarjeta que
// nadie dio y el bot la confirmaba.
// Ahora lo que no mide exactamente 16 (tarjeta) u 8 empezando por 5 (celular) NO
// se clasifica. El bot se queda sin beneficiario y lo vuelve a pedir con
// naturalidad, que es lo que ya hace hoy cuando no reconoce un numero — sin
// explicar formatos, que el prompt lo prohibe.
const norm=texto_escrito.replace(/(?<=\d)[ \t\-_.  ]+(?=\d)/g,'');
const runs=norm.match(/\d+/g)||[];
for(const run of runs){
  let s=run;
  if(s.startsWith('0053')&&s.length===12)s=s.slice(4);
  else if(s.startsWith('53')&&s.length===10)s=s.slice(2);
  if(s.length===16){add(tarjetas,s);continue}
  if(s.length===8&&esMovilCU(s)){add(celulares,s);continue}
  if(s.length>=8)add(numeros_no_reconocidos,run);
}let comprobante=null,comprobante_duplicado=false,tarjeta_de_imagen=false;const alertas=[];const comprobantes=[];
// Una foto de una transferencia NUESTRA a una tarjeta CUP puede traer monto y
// tarjeta, pero no es un deposito del cliente. Si la vision la confunde con
// comprobante, recuperamos la tarjeta y la mandamos por la via beneficiario.
const extraerTarjeta16 = valor => {
  const m=String(valor??'').match(/(?:^|[^0-9])((?:[0-9][ \t._-]*){16})(?![0-9])/);
  if(!m)return null;
  const d=m[1].replace(/\D/g,'');
  return d.length===16?d:null;
};
const tarjetaDeVision = v => {
  for(const k of ['numero_tarjeta','tarjeta','card_number','destinatario','banco_destino','referencia']){
    const d=extraerTarjeta16(v?.[k]);
    if(d)return d;
  }
  if(v?.tipo==='otro'&&/(tarjeta|card|cup)/i.test(String(v?.descripcion??'')))
    return extraerTarjeta16(v?.descripcion);
  return null;
};
const comprobanteConTransaccion = v => {
  const ref=String(v?.referencia??'').replace(/\D/g,'');
  const estado=String(v?.estado??'').toUpperCase();
  // Los TransID reales medidos son de 12–14 digitos. Una tarjeta CUP son 16.
  return ref.length>=10&&ref.length<=15&&(estado==='EXITOSA'||estado==='PROCESANDO');
};
// FOTO DEL CARNET (B1.4, 2026-09-29): candidato determinista para la entrega
// en efectivo (efectivo_usd). La PRIMERA imagen que, tras la reclasificacion de
// tarjeta de arriba, se quede en tipo 'otro' (ni comprobante, ni tarjeta_cubana,
// ni cuenta_zelle) es candidata a ser la foto del carnet -- el registro real
// (y la guarda de no pisar una foto ya guardada) lo hace 'Registrar carnet
// efectivo' en SQL, este nodo solo transporta el wamid.
let foto_otro_wamid=null;let foto_carnet_wamid=null;let foto_carnet_nombre=null;let comprobantes_repetidos=0;
vision.forEach((v,i)=>{
  const tarjetaVista=tarjetaDeVision(v);
  // Si no hay TransID real, la imagen de monto+tarjeta es destino, no deposito.
  if((v?.tipo==='comprobante'&&!comprobanteConTransaccion(v)||v?.tipo==='otro')&&tarjetaVista)
    v={tipo:'tarjeta_cubana',numero_tarjeta:tarjetaVista,celular:v.celular};
  if(v.tipo==='comprobante'){
    // (178) El MISMO comprobante dos veces en la rafaga (misma Ref, mismo importe y moneda;
    // otra foto o captura del mismo pago) es UN deposito. Onelsi 29-sep: se sumo dos veces
    // (10,000 en vez de 5,000) y la rafaga acabo en Incidencia.
    const refV=String(v.referencia??'').replace(/\D/g,'');
    if(refV.length>=10&&comprobantes.some(c=>String(c.referencia??'').replace(/\D/g,'')===refV&&Number(c.monto)===Number(v.monto)&&String(c.moneda??'')===String(v.moneda??''))){comprobantes_repetidos++;return;}
    comprobantes.push(v);if(!comprobante)comprobante=v;if(dedup[i]?.duplicado)comprobante_duplicado=true;if(dedup[i]?.comp_id_original){v.comp_id=dedup[i].comp_id_original;}(v.alertas??[]).forEach(a=>alertas.push(a));
  }else if(v.tipo==='tarjeta_cubana'){
    const t=String(v.numero_tarjeta??tarjetaVista??'').replace(/\D/g,'');
    if(t.length===16&&!tarjetas.includes(t)){tarjetas.push(t);tarjeta_de_imagen=true}
    if(v.celular){const c=String(v.celular).replace(/\D/g,'').slice(-8);if(esMovilCU(c))add(celulares,c)}
  }else if(v.tipo==='carnet'){
    // CARNET RECONOCIDO (87, 3-oct-2026): solo esta imagen puede ser la foto del carnet de una entrega en efectivo.
    // Lleva la alerta de imagen no-comprobante para que el Decisor siga prohibiendo hablar de depositos.
    alertas.push('Imagen no reconocida: carnet de identidad'+(v.nombre?' de '+v.nombre:'')+' (no es un comprobante)');
    if(!foto_carnet_wamid&&v.wamid){foto_carnet_wamid=v.wamid;foto_carnet_nombre=v.nombre??null;}
  }else if(v.tipo==='otro'){alertas.push('Imagen no reconocida: '+(v.descripcion??''));if(!foto_otro_wamid&&v.wamid)foto_otro_wamid=v.wamid}
});
// --- VARIOS COMPROBANTES EN LA MISMA RAFAGA (11-ago-2026) ------------------
// Hasta hoy el bucle de arriba hacia `comprobante = v` y se quedaba con el
// ULTIMO. El 11-ago Melih (5926131647) mando 27.000 + 300 juntos: la vision
// leyo LOS DOS perfectos y el de 27.000 se descarto en silencio.
// `comprobante` NO se quita —lo lee medio flujo y romperlo es tocar todo— pero
// ahora es el PRIMERO, no el ultimo, y ademas se publica la rafaga entera.
// LA SUMA LA HACE ESTE NODO Y LA VERIFICA EL SQL. El agente no calcula nunca:
// pedirle que deduzca el total es lenguaje deliberativo y rompe a DeepSeek en
// el turno siguiente (ver 11-lenguaje-deliberativo-rompe-deepseek.md).
const comprobantes_n=comprobantes.length;
const comprobantes_total=comprobantes.reduce((s,c)=>s+(Number(c.monto)||0),0);
// SUMABLES = se pueden sumar SIN que lo mire una persona. Basta que UNO falle
// para que no. `monto > 0` esta a proposito: un comprobante leido con importe 0
// bajaria el total sin que se note en ninguna alerta. Y la MONEDA tiene que ser
// la misma en todos: la vision devuelve GYD, MXN o USD, y sumar dos monedas
// distintas daria un numero que no significa nada.
const comprobantes_sumables=comprobantes.length>0&&!comprobante_duplicado&&comprobantes.every(c=>String(c.estado??'').toUpperCase()==='EXITOSA'&&String(c.referencia??'').replace(/[^0-9]/g,'').length>=10&&Number(c.monto)>0&&String(c.moneda??'')===String(comprobantes[0].moneda??'')&&!(c.alertas??[]).join(' ').toLowerCase().includes('no esta claro'));
// La alerta SOLO se levanta si no se pueden sumar. `alertas` significa "algo va
// mal en esta rafaga", y de ella cuelga la etapa del deal (`Registrar deposito
// auto`: alertas.length > 0 -> Incidencia). Una rafaga sumable ya no es una
// anomalia y no debe mandar el envio a Incidencia.
if(comprobantes_n>1&&!comprobantes_sumables)alertas.push('El cliente mando MAS de un comprobante en la misma rafaga');
const tarjeta=tarjetas[0]??null;const celular=celulares[0]??null;const multi_beneficiario=tarjetas.length>1;
// El cliente esta corrigiendo datos que ya dio: lo parcial guardado queda invalidado.
const correccion=/(me equivoqu|no es a esa|no es esa|esa no es|no son esos|esos no son|otra tarjeta|otro celular|cambi[ae]?\s+(la tarjeta|el celular|el numero))/i.test(texto);

// --- ZELLE (aditivo 6-ago-2026): NO toca la deteccion cubana de arriba.
// Solo AÑADE campos al snapshot. De momento ningun nodo los lee: fase de observacion.
// REGLA: los datos del Zelle se guardan TAL CUAL los escribio el cliente. Vienen del
// intermediario y no se tocan. La normalizacion se usa solo para DECIDIR si parece un
// numero de EEUU, nunca para almacenar ni para mostrar.
// UNICA excepcion: el correo se pasa a minusculas. La caja no lleva informacion
// (Gmail y Zelle la ignoran) y asi el mismo correo no se guarda dos veces. El
// TELEFONO no se toca: ahi normalizar seria quitar caracteres y un digito mal
// escrito quedaria invisible.
const zelle_correos=[],zelle_celulares=[];
// NORMALIZAR EL NUMERO DE EEUU (12-ago, pedido de Humberto).
// Hasta hoy se guardaba tal cual lo escribio el cliente, y eso dejaba entrar
// basura: de `(786) 861-3281` se guardaba `786) 861-3281` — sin el parentesis de
// apertura, porque el regex empieza a capturar en un digito. Un cliente real lo
// sufrio el 12-ago a las 16:48.
// La regla vieja era no normalizar para que un digito mal escrito no quedara
// invisible. Se respeta: aqui se quitan SOLO separadores, NUNCA un digito, y si
// no salen exactamente 10 (u 11 con el 1 del pais) NO se acepta como Zelle. Asi
// el numero llega completo y ningun error se esconde: se descarta.
// El codigo de pais se cae, que da igual para Zelle; lo que no puede faltar son
// los 10 digitos.
const normUS=n=>{const d=String(n??'').replace(/\D/g,'');
  if(d.length===11&&d[0]==='1')return d.slice(1);
  if(d.length===10&&d[0]!=='5')return d;
  return null};
