WITH asignar AS (
  SELECT d.id, c.contact_id
    FROM cerebro_registrar_derivacion(
      $1::uuid,
      'El caso requiere atención de un operador.',
      'solicitud_cliente',
      true
    ) d
    JOIN conversations c ON c.id = d.id
), datos AS (SELECT a.id, c.name AS cliente_nombre, c.phone AS cliente_phone FROM asignar a JOIN contacts c ON c.id=a.contact_id), aviso AS (SELECT net.http_post(url := cerebro_config_get('notify_url'), headers := jsonb_build_object('Content-Type','application/json','X-Cerebro-Secret', cerebro_config_get('notify_secret')), body := jsonb_build_object('type','DERIVACION','cliente_nombre',(SELECT cliente_nombre FROM datos),'cliente_phone',(SELECT cliente_phone FROM datos))) AS req_id FROM datos) SELECT a.id, 'derivado' AS accion FROM asignar a LEFT JOIN aviso ON true;

