const V_BANCOS = { '0699': 'BANDEC', '1299': 'BPA', '9598': 'Banco Metropolitano' };
const V_TIPOS = { '9200': 'CUP', '9204': 'CUP', '9224': 'CUP', '9227': 'CUP', '9205': 'CUP', '9238': 'CUP', '9206': 'CUP', '9210': 'CUP', '9211': 'CUP', '9212': 'CUP', '9213': 'CUP', '9216': 'CUP', '9233': 'CUP', '9237': 'CUP', '9225': 'USD', '9235': 'USD', '9240': 'USD', '9226': 'USD', '9228': 'USD', '9250': 'USD', '9229': 'USD' };
function vLuhn(s) { let t = 0; for (let i = 0; i < s.length; i++) { let d = +s[s.length - 1 - i]; if (i % 2) { d *= 2; if (d > 9) d -= 9; } t += d; } return t % 10 === 0; }
function vTarjeta(n) {
  n = String(n ?? '').replace(/\D/g, '');
  if (n.length !== 16 || !(n.startsWith('92') || n.startsWith('9760')) || !vLuhn(n)) return { ok: false, numero: n };
  if (n.startsWith('97600390')) return { ok: true, numero: n, banco: 'Clasica (Fincimex)', moneda: 'USD' };
  return { ok: true, numero: n, banco: V_BANCOS[n.slice(4, 8)] || 'desconocido', moneda: V_TIPOS[n.slice(0, 4)] || 'desconocida' };
}
function vTelUS(s) {
  let n = String(s ?? '').replace(/\D/g, '');
  if (n.length === 11 && n.startsWith('1')) n = n.slice(1);
  return n.length === 10 && /^[2-9][0-8]\d[2-9]\d{6}$/.test(n) && V_US.has(n.slice(0, 3));
}
function vCelCU(s) {
  let n = String(s ?? '').replace(/\D/g, '');
  if (n.length === 10 && n.startsWith('53')) n = n.slice(2);
  if (n.length === 12 && n.startsWith('0053')) n = n.slice(4);
  return /^(5\d|6[13])\d{6}$/.test(n);
}
function vCarnet(s) {
  const n = String(s ?? '').replace(/\D/g, '');
  if (n.length !== 11) return false;
  const yy = +n.slice(0, 2), mm = +n.slice(2, 4), dd = +n.slice(4, 6), c = n[6];
  const y = (c === '9' ? 1800 : (c <= '5' ? 1900 : 2000)) + yy;
  const f = new Date(Date.UTC(y, mm - 1, dd));
  return f.getUTCFullYear() === y && f.getUTCMonth() === mm - 1 && f.getUTCDate() === dd;
}
function vRefMMG(s) { return /^[12]\d{13}$/.test(String(s ?? '').replace(/\D/g, '')); }
function vTextos(o, acc = []) {
  if (o == null) return acc;
  if (typeof o === 'object') { for (const v of Object.values(o)) vTextos(v, acc); } else acc.push(String(o));
  return acc;
}
function verificarLectura(a) {
  if (!a || typeof a !== 'object') return a;
  const t = vTextos(a).join(' | ');
  const tarjetas = [...t.matchAll(/(?<!\d)(\d{4})[ \-]?(\d{4})[ \-]?(\d{4})[ \-]?(\d{4})(?!\d)/g)].map((m) => m.slice(1).join('')).filter((n) => vTarjeta(n).ok);
  const telsUS = [...t.matchAll(/(?<![\d])(?:\+?1[\s\-\.]*)?\(?[2-9][0-8]\d\)?[\s\-\.]*[2-9]\d{2}[\s\-\.]*\d{4}(?!\d)/g)].map((m) => m[0].trim()).filter(vTelUS);
  const correos = [...t.matchAll(/[\w.+\-]+@[\w\-]+\.[A-Za-z]{2,}/g)].map((m) => m[0]);
  const refsMMG = [...t.replace(/(?<=\d)[ \-](?=\d)/g, '').matchAll(/(?<!\d)[12]\d{13}(?!\d)/g)].map((m) => m[0]);
  const cambios = [];
  let r = a;
  // 1) Reclasificar SOLO lo que el modelo dejo como "otro" o un comprobante que no es de MMG:
  //    los comprobantes con referencia MMG nunca se tocan.
  const comprobanteAjeno = a.tipo === 'comprobante' && refsMMG.length === 0;
  if ((a.tipo === 'otro' || comprobanteAjeno) && tarjetas.length > 0) {
    const cel = (t.match(/(?<!\d)(?:\+?53[\s\-]?)?((?:5\d|6[13])\d{6})(?!\d)/) || [])[1] || null;
    r = { tipo: 'tarjeta_cubana', numero_tarjeta: tarjetas[0], celular: cel };
    cambios.push('reclasificada como tarjeta_cubana (era ' + a.tipo + ')');
  } else if ((a.tipo === 'otro' || (comprobanteAjeno && /zelle/i.test(t))) && (telsUS.length > 0 || correos.length > 0)) {
    r = { tipo: 'cuenta_zelle', nombre: null, celular_us: telsUS[0] || null, correo: correos[0] || null };
    cambios.push('reclasificada como cuenta_zelle (era ' + a.tipo + ')');
  }
  // 2) Verificar cada dato segun su tipo
  const v = { ok: true, checks: {}, cambios };
  if (r.tipo === 'comprobante') {
    v.checks.referencia_formato = vRefMMG(r.referencia);
    if (r.moneda === 'GYD' && Number(r.monto) > 0 && Number(r.monto) < 1000) v.checks.monto_sensato = false;
  } else if (r.tipo === 'tarjeta_cubana') {
    if (r.numero_tarjeta) { const x = vTarjeta(r.numero_tarjeta); v.checks.tarjeta = x.ok; if (x.ok) { v.banco = x.banco; v.moneda_tarjeta = x.moneda; } }
    if (r.celular) v.checks.celular_cubano = vCelCU(r.celular);
    if (!r.numero_tarjeta && !r.celular) v.checks.dato_tarjeta = false;
  } else if (r.tipo === 'cuenta_zelle') {
    if (r.celular_us) v.checks.telefono_eeuu = vTelUS(r.celular_us);
    if (!r.celular_us && !r.correo) v.checks.dato_zelle = false;
  } else if (r.tipo === 'carnet') {
    const n = String(r.numero_identidad ?? '').replace(/\D/g, '');
    if (n && !/[A-Za-z]/.test(String(r.numero_identidad))) v.checks.carnet = vCarnet(n);
  }
  v.ok = Object.values(v.checks).every((x) => x !== false);
  return { ...r, verificacion: v };
}
// ==== FIN VERIFICACION ====

// Parsea la PRIMERA lectura de vision y la deja lista para preguntarle al libro
