    render_chars: m.chars, render_preguntas: m.preguntas,
    render_chars_original: metrica(original).chars,
    render_preguntas_original: metrica(original).preguntas,
    render_candidato: (modo === 'shadow' ? (cand ?? null) : undefined) } }];
}

if (modo === 'off') { return salir(original, false, 'apagado', null); }
if (typeof original !== 'string' || !original.trim()) {
  return salir(original, false, 'salida_no_es_texto', null);
}
// SKIP es del Decisor y de la frontera, no del renderer.
if (/^\s*SKIP\b/i.test(original)) { return salir(original, false, 'skip', null); }

// --- unidades: parrafos, y dentro frases -----------------------------------
const parrafos = original.split(/\n{2,}/);
const trocear = (p) => p.split(/(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÑ¿¡])/).filter(x => x.trim());

// --- 1 · REVELACION PROGRESIVA: fuera el paso n+2 ---------------------------
// No se toca la frase si es la ultima accionable (seria dejar al cliente sin
// saber que hacer) ni si lleva una cifra.
const FUTURO = /(una vez que|cuando (confirmemos|verifiquemos|tengamos|se verifique)|mas adelante|más adelante|posteriormente|el siguiente paso|luego (le|se))/i;
// --- 2 · REPETICION: fuera lo que ya dijo el bot en su mensaje anterior ------
const norm = (t) => String(t).toLowerCase().replace(/[^a-z0-9áéíóúñ ]/gi, ' ').replace(/\s+/g, ' ').trim();
const ultimoNorm = norm(ultimoBot);
const CRITICA = /(verificad|tarjeta|celular|zelle|cuenta|transferencia|dep[oó]sito|gyd|cup|usd)/i;
// --- 3 · MULETILLA CEREMONIAL duplicada -------------------------------------
const MULETILLA = /^(perfecto|listo|dale|anotado|entendido|claro|de acuerdo)[.,!]?\s*$/i;

const fuera = [];
const nuevos = [];
for (const p of parrafos) {
  const frases = trocear(p);
  const quedan = [];
  for (let i = 0; i < frases.length; i++) {
    const f = frases[i].trim();
    const esUltima = (p === parrafos[parrafos.length - 1]) && (i === frases.length - 1);
    const tieneCifra = /\d/.test(f);
    if (!esUltima && !tieneCifra && FUTURO.test(f) && plan && plan.siguiente_accion !== 'ninguna') {
      fuera.push('futuro'); continue;
    }
    if (!esUltima && !tieneCifra && MULETILLA.test(f) && quedan.length) { fuera.push('muletilla'); continue; }
    if (!esUltima && ultimoNorm && !CRITICA.test(f)) {
      const fn = norm(f);
      if (fn.length > 25 && ultimoNorm.includes(fn)) { fuera.push('repetido'); continue; }
    }
    quedan.push(f);
  }
  if (quedan.length) { nuevos.push(quedan.join(' ')); }
}
// Lo que queda tras QUITAR. Esta fase solo puede acortar: es la que se compara
// con el original para no colar nada de mas.
const compacto = nuevos.join('\n\n').trim();
let candidato = compacto;

// --- 4 · VARIACION CONTROLADA ------------------------------------------------
// Las mismas frases, palabra por palabra, cientos de veces: «¿Me pasa los datos
// de quien recibe?» 192 veces en 31 dias, la presentacion 297. Son correctas;
// lo que cansa es que sean siempre la misma. Variantes validadas, elegidas de
// forma determinista por conversacion: la misma conversacion no cambia de voz a
// mitad, y dos clientes distintos no oyen lo mismo.
// NINGUNA variante empieza por un acuse («Anotado», «Entendido», «Perfecto»…).
// La primera version si lo hacia y producia cosas como «Anotado. Anotada la
// cuenta Zelle» o «Entendido, Queda registrada…»: legacy ya abre la frase con el
// acuse, asi que la variante no puede traer otro. Y todas empiezan con la misma
// palabra que la original, para no romper la mayuscula cuando la frase va detras
// de una coma («Entendido, la cuenta Zelle queda asi:»).
const VARIANTES = [
  [/¿Me pasa los datos de quien recibe\?/gi,
   ['¿Me pasa los datos de quien recibe?',
    '¿Me indica los datos de quien recibe en Cuba?',
    '¿Me comparte los datos de la persona que recibe?']],
  [/aqu[ií] estoy pendiente\./gi,
   ['aquí estoy pendiente.',
    'aquí le espero.',
    'aquí quedo pendiente.']],
  [/([Ll])a cuenta Zelle queda as[ií]:/g,
   ['$1a cuenta Zelle queda así:',
    '$1a cuenta Zelle queda anotada así:',
    '$1a cuenta Zelle es la siguiente:']],
  [/¿Desde d[oó]nde va a depositar, desde la app o con un agente\?/gi,
   ['¿Desde dónde va a depositar, desde la app o con un agente?',
    '¿El depósito lo hace desde la app o con un agente?',
    '¿Va a depositar por la app o con un agente?']],
];
// Red de seguridad de la variacion: si el candidato acaba con dos acuses
// pegados y el original no los tenia, la variacion se descarta.
const RE_DOBLE_ACUSE = /\b(anotado|entendido|perfecto|listo|dale|claro)\b[.,]\s+(anotad|queda registrad|entendido|perfecto|listo|dale)/i;
let semilla = 0;
try {
  const cid = String($('Decisor').first().json?.conversation_id ?? '');
  for (const ch of cid) { semilla = (semilla * 31 + ch.charCodeAt(0)) % 100000; }
} catch (e) {}
let variado = 0;
for (const [re, opciones] of VARIANTES) {
  if (re.test(candidato)) {
    const elegida = opciones[(semilla + variado) % opciones.length];
    candidato = candidato.replace(re, elegida);
    variado++;
  }
}

// --- 5 · COMPROBACIONES: si algo no cuadra, se envia lo del modelo -----------
const digitos = (t) => (String(t).match(/\d/g) || []).sort().join('');
const soloTexto = (t) => String(t).replace(/\s+/g, ' ').trim();
if (!candidato) { return salir(original, false, 'candidato_vacio', null); }
if (digitos(candidato) !== digitos(original)) {
  // cualquier cifra distinta, de mas o de menos, invalida el candidato
  return salir(original, false, 'cifras_distintas', candidato);
}
if ((candidato.match(/\?/g) || []).length > (original.match(/\?/g) || []).length) {
  return salir(original, false, 'mas_preguntas', candidato);
}
// La COMPRESION no puede alargar. La VARIACION si puede mover unos caracteres
// («¿Me comparte los datos de la persona que recibe?» es una linea mas larga que
// «¿Me pasa los datos de quien recibe?» y sigue siendo mejor), asi que se le deja
// un margen corto y acotado.
if (soloTexto(compacto).length > soloTexto(original).length) {
  return salir(original, false, 'compresion_alargo', candidato);
}
if (soloTexto(candidato).length > soloTexto(compacto).length + 40) {
  return salir(original, false, 'variacion_demasiado_larga', candidato);
}
if (/\n{2,}/.test(candidato) && candidato.split(/\n{2,}/).length > original.split(/\n{2,}/).length) {
  return salir(original, false, 'mas_unidades', candidato);
}

if (variado && RE_DOBLE_ACUSE.test(candidato) && !RE_DOBLE_ACUSE.test(original)) {
  return salir(original, false, 'variacion_con_doble_acuse', candidato);
}

const motivo = fuera.length || variado ? ('quitado:' + fuera.join('+') + '|variado:' + variado) : 'sin_cambios';
if (modo === 'on') { return salir(candidato, candidato !== original, motivo, candidato); }
return salir(original, false, 'sombra:' + motivo, candidato);

// Reune lo medible del turno. Todo con try/catch: la telemetria no puede tumbar
// el turno de un cliente. Lo que n8n no expone a un nodo Code (los tokens del
// modelo viven en los datos de ejecucion, no en los items) queda a null y se
// documenta: no se inventa.
const V = (f, d) => { try { const r = f(); return r === undefined ? d : r; } catch (e) { return d; } };
const dec = V(() => $('Decisor').first().json, {});
const norm = V(() => $('Normalizar formato').first().json, {});
const texto = String(norm.output ?? '');
const valla = V(() => $('Valla de propiedad').first().json, null);
const pars = V(() => $('Parsear vision').all().map(i => i.json), []);
const cand = V(() => $('Preparar candidatos').all().map(i => i.json), []);
const audios = V(() => $('Separar audios').all().length, 0);

// ¿el envio directo fallo? el nodo HTTP lleva onError:continue, asi que un
// fallo llega como item con `error` en vez de tumbar el turno.
const envio = V(() => $('Responder por WaCRM').first().json, null);
const envio_fallo = !!(envio && envio.error);

// POR QUE CALLO (observabilidad, 2026-09-26). En produccion el 53% de los
// turnos salen como 'silencio' y no se sabia por que: la mayoria son las
// ejecuciones de una rafaga que ceden el lote a la ultima. Se deduce del camino
// que corrio; null cuando el turno si respondio. Solo mide: no cambia la ruta.
const corrio = (nombre) => V(() => $(nombre).isExecuted === true, false);
const MOTIVO_DECISOR = {
  'bot pausado a mano en esta conversacion': 'bot_pausado',
  'chat oculto por el operador': 'chat_oculto',
  'chat asignado a humano': 'chat_asignado',
  'un humano del equipo acaba de escribir': 'humano_reciente',
  'mensaje del admin': 'mensaje_admin',
};
// Un turno que SI entrego respuesta no tiene motivo de silencio. 'Cerrar lote'
// corre al final de todo turno que proceso un lote (visto en staging, ejecucion
// 244499): solo significa 'no habia lote' si el Decisor ni siquiera corrio.
const entrego = !!(texto && texto !== 'SKIP') && !valla?.bloquear;
const motivo_silencio = entrego ? null
  : corrio('Otro proceso tomara el lote') ? 'rafaga_otro_proceso'
  : corrio('Duplicado descartado') ? 'evento_duplicado'
  : corrio('Replay descartado') ? 'replay'
  : dec.ruta === 'silencio' ? (MOTIVO_DECISOR[dec.motivo] ?? ('decisor:' + String(dec.motivo ?? '?')))
  : corrio('Silencio por limite') ? 'limite_abuso'
  : corrio('Silencio por propiedad') ? 'valla_propiedad'
  : corrio('SKIP - no responder') ? 'modelo_skip'
  : (corrio('Cerrar lote') && !corrio('Decisor')) ? 'sin_lote'
  : null;

const datos = {
  conversation_id: dec.conversation_id ?? V(() => $('Validar evento').first().json.conversation_id, null),
  ruta: dec.ruta ?? 'silencio',
  modelo_llamado: V(() => !!$('Agente Remesas').first().json, false),
  prompt_chars: String(dec.mensaje ?? '').length || null,
  contexto_chars: V(() => dec.plan?.contexto_chars, null),
  vision_calls: cand.reduce((n, c) => n + Number(c.vision_calls ?? 4), 0) || null,
  vision_policy: cand[0]?.vision_policy ?? null,
  vision_rotation_selected: pars[0]?.giro_elegido ?? null,
  vision_ledger_confirmed: pars.length ? /libro/.test(String(pars[0]?.arbitro ?? '')) : null,
  audio_calls: audios || null,
  ownership_fence_blocked: !!valla?.bloquear,
  ownership_fence_reason: valla?.motivo ?? null,
  response_chars: texto && texto !== 'SKIP' ? texto.length : 0,
  questions: texto ? (texto.match(/\?/g) || []).length : 0,
  entrega: valla?.bloquear ? 'bloqueado'
          : (V(() => $('Encolar en outbox').first().json.enviar_directo, null) === false ? 'outbox'
          : (texto && texto !== 'SKIP' ? (envio_fallo ? 'fallido' : 'enviado') : 'skip')),
  renderer_modo: norm.render_modo ?? null,
  renderer_aplicado: norm.render_aplicado ?? null,
  renderer_motivo: norm.render_motivo ?? null,
  renderer_chars: norm.render_chars ?? null,
  renderer_questions: norm.render_preguntas ?? null,
  // Presentation Compiler V2 (R6 §12): solo estructura, ninguna copia del
  // mensaje, ningun texto, ninguna PII. Va en el `extra` de la telemetria que
  // ya existe: no hace falta migracion nueva.
  extra: { candidato_renderer_chars: norm.render_chars ?? null,
           original_chars: norm.render_chars_original ?? null,
           presentation_compiler_mode: norm.pc_modo ?? null,
           presentation_compiler_applied: norm.pc_aplicado ?? null,
           presentation_compiler_would_apply: norm.pc_candidato_aplicaria ?? null,
           presentation_compiler_reason: norm.pc_motivo ?? null,
           presentation_compiler_operations: norm.pc_ops ?? null,
           paragraph_breaks_added: norm.pc_cortes ?? null,
           bold_spans_added: norm.pc_negritas ?? null,
           hold_reason: norm.pc_hold ?? null,
           motivo_silencio },
};
return [{ json: { telemetria: JSON.stringify(datos) } }];

// CU-V2 R3. Mide la SEMANTICA del turno: banderas y veredicto, nunca contenido.
// Mismo criterio que `Medir el turno`: todo con try/catch, porque una medicion
// jamas puede costarle la respuesta a un cliente. Este nodo corre DESPUES de
// cerrar el lote y de la telemetria; el cliente ya tiene su mensaje.
const V = (f, d) => { try { const r = f(); return r === undefined ? d : r; } catch (e) { return d; } };

const dec   = V(() => $('Decisor').first().json, {});
const norm  = V(() => $('Normalizar formato').first().json, {});
const snap  = V(() => $('Snapshot final').first().json, {});
const merge = V(() => $('Merge beneficiario').first().json, {});
const compl = V(() => $('Evaluar completitud').first().json, {});
const lote  = V(() => $('Reclamar lote').all().map(i => i.json), []);
const texto = String(norm.output ?? '');
const respondio = !!(texto && texto !== 'SKIP');

// ¿Cuantas veces corrio `Evaluar completitud`? Dos = el debounce adaptativo
// alargo la espera. R2 dejo esto sin poder medir; es el hueco que esta fila
// viene a tapar.
const corridas = (() => {
  let n = 0;
  try { while (n < 5 && $('Evaluar completitud').all(0, n).length) { n++; } } catch (e) {}
  return n;
})();

// --- detectores de texto del gate -----------------------------------------
// Miran la respuesta y guardan el VEREDICTO, nunca la respuesta. G1, G2, G4,
// G5, G6 y G8 necesitan el plan del turno y se evaluan fuera de linea con
// tools/cu-v2. Aqui solo va lo que se decide con el texto delante.
const VIAS = { 'zelle': 'zelle', 'clasica': 'clasica', 'clásica': 'clasica',
               'tropical': 'tropical', 'cup': 'cuban_card' };
const vias_mencionadas = [...new Set(Object.keys(VIAS)
  .filter(t => new RegExp('(?<![\\w])' + t + '(?![\\w])', 'i').test(texto))
  .map(t => VIAS[t]))];

// «tarjeta» sola no es la cubana: existen la Clasica y la Tropical. El alcance
// del desambiguador es el parrafo (R3 §4).
const DESAMB = ['cubana', 'cubanas', 'clasica', 'clásica', 'tropical', 'cup'];
let tarjeta_generica = false;
for (const p of texto.split(/\n\s*\n/)) {
  const b = p.toLowerCase();
  if (/(?<![\w])tarjetas?(?![\w])/i.test(p) && !DESAMB.some(d => b.includes(d))) {
    tarjeta_generica = true;
    break;
  }
}

// G3 solo cuenta cuando la via USD esta en juego (2026-09-26). En CUP el prompt
// ORDENA pedir 'la tarjeta y el celular' sin aclarar formato: ahi 'tarjeta' es
// la cubana y marcarlo era una falsa alarma (39 por semana en produccion). Con
// USD si es ambiguo: la Clasica y la Tropical tambien son tarjetas.
const USD = /(?<![\w])(usd|d[oó]lar(es)?|zelle|cl[aá]sica|tropical)(?![\w])/i;
const ruta_usd = !!snap.datos_zelle
  || USD.test(String(snap.texto_completo ?? ''))
  || USD.test(texto);

const preguntas = respondio ? (texto.match(/\?/g) || []).length : 0;
const cta_al_final = (!respondio || preguntas === 0) ? null
  : !/[\wáéíóúñ]/i.test(texto.slice(texto.lastIndexOf('?') + 1));

const reglas = [];
if (respondio) {
  if (tarjeta_generica && ruta_usd) { reglas.push('G3_GENERIC_CARD_AMBIGUITY'); }
  if (preguntas > 1) { reglas.push('G7_MULTIPLE_CTA'); }
  if (cta_al_final === false) { reglas.push('G7_CTA_NOT_LAST'); }
}

const cuenta = v => Array.isArray(v) ? v.length : null;
const datos = {
  conversation_id: dec.conversation_id
    ?? V(() => $('Validar evento').first().json.conversation_id, null),
  eventos_en_lote: lote.length || null,
  eventos_texto:  lote.filter(e => e.tipo === 'text').length,
  eventos_imagen: lote.filter(e => e.tipo === 'image').length,
  eventos_audio:  lote.filter(e => e.tipo === 'audio').length,
  debounce_extendido: corridas > 1 ? true : (compl.incompleto ?? null),
  run_index: corridas ? corridas - 1 : null,
  correccion_detectada: snap.correccion ?? null,
  multi_beneficiario: snap.multi_beneficiario ?? null,
  tarjetas_n: cuenta(snap.tarjetas),
  celulares_n: cuenta(snap.celulares),
  zelle_completo: V(() => !!(merge.zelle_cuenta && merge.zelle_nombre), null),
  beneficiario_completo: V(() => !!(merge.tarjeta_final && merge.celular_final), null),
  comprobantes_n: typeof snap.comprobantes === 'number' ? snap.comprobantes
                                                       : cuenta(snap.comprobantes),
  respuesta_chars: respondio ? texto.length : 0,
  respuesta_preguntas: preguntas,
  cta_al_final: cta_al_final,
  vias_mencionadas: vias_mencionadas,
  tarjeta_generica: tarjeta_generica,
  gate_reglas_violadas: reglas,
};
return [{ json: { auditoria: JSON.stringify(datos) } }];

// ============================================================================
// PRESENTATION COMPILER V2 — port de produccion
// ============================================================================
// Port EXACTO de tools/cu-v2/compilador.py, la version que sobrevivio a R5:
// 271 turnos reales, 0 regresiones, y el dueno lo prefirio 5 a 1 a ciegas.
//
// Va DESPUES de `Renderer conversacional` (que en sombra deja pasar el texto
// ORIGINAL) y ANTES de `Normalizar formato`, que sigue siendo la frontera
// fail-closed de siempre y no se toca.
//
// Bandera propia `opt_presentation_compiler_v2` en cerebro_config:
//   off     -> no hace nada
//   shadow  -> calcula el candidato y lo mide, pero ENVIA EL ORIGINAL
//   on      -> envia el candidato
//
// NO reescribe, no parafrasea, no resume, no borra informacion, no resuelve dos
// CTA, no crea listas, no quita acuses y no reordena oraciones inseguras. Hace
// tres cosas y para:
//
//   INSERT_PARAGRAPH_BREAK · APPLY_BOLD_TO_FACT_SPAN · CTA_MOVE_TO_END
//
// FAIL OPEN: ante cualquier excepcion, schema raro o mismatch numerico, sale el
// ORIGINAL. Esto nunca puede impedir una respuesta.
// ----------------------------------------------------------------------------

// --- limites de palabra ------------------------------------------------------
// En Python `\b` es Unicode; en JavaScript es ASCII, asi que `\btambién\b` no
// casaria igual. Se escriben los limites a mano para que el port sea EXACTO.
const W = '0-9A-Za-z_\\u00C0-\\u024F';
const B0 = `(?<![${W}])`;
const B1 = `(?![${W}])`;

const NO_APPLY = 'NO_APPLY';
const HOLD_MULTIPLE_CTA = 'COMPILER_HOLD_MULTIPLE_REQUIRED_CTA';
const HOLD_UNSUPPORTED = 'COMPILER_HOLD_UNSUPPORTED_SEGMENT';

const INSERT_PARAGRAPH_BREAK = 'INSERT_PARAGRAPH_BREAK';
const REMOVE_PARAGRAPH_BREAK = 'REMOVE_PARAGRAPH_BREAK';
const APPLY_BOLD_TO_FACT_SPAN = 'APPLY_BOLD_TO_FACT_SPAN';
const CTA_MOVE_TO_END = 'CTA_MOVE_TO_END';
const DROP_REDUNDANT_ACK = 'DROP_REDUNDANT_ACK';
const DROP_REDUNDANT_CLOSING = 'DROP_REDUNDANT_CLOSING';

const ACK = 'ACKNOWLEDGEMENT', ANSWER = 'ANSWER', FACTUAL = 'FACTUAL_CONTEXT';
const EXPLANATION = 'EXPLANATION', LIST = 'LIST', CTA = 'CTA';
const CLOSING = 'CLOSING', PROCESS = 'PROCESS_CLAIM';

// El 86,7 % de los mensajes de la casa lleva DOS negritas o menos, y el dueno
// rechazo a ciegas el unico compilado que subia a tres. Congelado en 2.
const MAX_NEGRITAS = 2;

const RE_ACK = new RegExp('^\\s*(perfecto|entendido|claro|anotado|listo|ok|vale|' +
  'de acuerdo|genial|buenos d[ií]as|buenas tardes|buenas noches|hola|gracias|' +
  'sin problema|por supuesto|correcto|dale)' + B1 + '[^.!?]*[.!?]?\\s*$', 'i');
const RE_CLOSING = new RegExp('^\\s*(quedamos pendientes?|aqu[ií] (estaremos|quedamos)|' +
  'cualquier cosa|gracias por confiar|estamos para servirle|un saludo|saludos)' + B1, 'i');
const RE_EXPLICATIVO = new RegExp(B0 + '(porque|ya que|es decir|esto significa|' +
  'lo que s[ií]|en otras palabras|o sea|de modo que)' + B1, 'i');
const RE_VINETA = /^\s*([-*•]|\d+[.)])\s+/;
const RE_ANAFORA = new RegExp(B0 + '(lo haga|lo hace|lo hizo|hacerlo|apenas lo|' +
  'en cuanto lo|eso|ello|esa|ese|esto|as[ií]|entonces|mientras tanto|por eso)' + B1, 'i');
const RE_CONECTOR = new RegExp('^\\s*(y|o|pero|para|as[ií]|tambi[eé]n|adem[aá]s|' +
  'entonces|luego|porque|ya que|si|como|que|aunque|sin embargo|por eso|' +
  'de todas formas)' + B1, 'i');
const RE_CTA_INICIAL = new RegExp('^\\s*(?:por favor,?\\s*)?(?:env[ií]eme|m[aá]ndeme|' +
  'escr[ií]bame|confirme|ind[ií]queme|d[ií]game|p[aá]seme|comp[aá]rtame)' + B1, 'i');

// Las mismas familias de G6 que etiquetan PROCESS_CLAIM en el reference.
const AFIRMACIONES = [
  new RegExp(B0 + '(?:lo |la |le |se lo )?reintento' + B1 + '|' + B0 + 'voy a (?:reintentar|intentarlo|intentar de nuevo)' + B1, 'i'),
  new RegExp(B0 + '(?:lo |la )?sumo' + B1 + '|' + B0 + 'estoy sumando' + B1 + '|' + B0 + 'voy a sumar' + B1, 'i'),
  new RegExp(B0 + '(?:lo |la )?reviso' + B1 + '|' + B0 + 'estoy revisando' + B1 + '|' + B0 + 'voy a revisar' + B1 + '|' + B0 + 'd[eé]jeme revisar', 'i'),
  new RegExp(B0 + '(?:lo |la |se lo )?separo' + B1, 'i'),
  new RegExp(B0 + 'transfiero' + B1 + '|' + B0 + 'voy a transferir' + B1 + '|' + B0 + 'hago (?:el env[ií]o|la transferencia)' + B1, 'i'),
  new RegExp(B0 + 'apruebo' + B1 + '|' + B0 + 'voy a aprobar' + B1, 'i'),
  new RegExp(B0 + '(?:lo |la )?verifico' + B1 + '|' + B0 + 'estoy verificando' + B1, 'i'),
  new RegExp(B0 + 'le paso con (?:un|una)' + B1 + '|' + B0 + 'voy a pasar(?:le)? con' + B1 + '|' + B0 + 'escalando' + B1, 'i'),
  new RegExp(B0 + 'reintentamos' + B1 + '|' + B0 + 'volvemos a intentar', 'i'),
  new RegExp(B0 + 'sumamos' + B1 + '|' + B0 + 'estamos sumando' + B1, 'i'),
  new RegExp(B0 + 'revisamos' + B1 + '|' + B0 + 'estamos revisando' + B1, 'i'),
  new RegExp(B0 + 'transferimos' + B1 + '|' + B0 + 'le hacemos el env[ií]o' + B1 + '|' + B0 + 'hacemos la transferencia' + B1 + '|' + B0 + 'sale ma[nñ]ana' + B1, 'i'),
  new RegExp(B0 + 'verificamos' + B1 + '|' + B0 + 'estamos verificando' + B1 + '|' + B0 + 'qued[oó] verificado' + B1, 'i'),
  new RegExp(B0 + '(?:una persona|el equipo|un operador|una persona del equipo)' + B1 +
             '[^.]{0,60}?' + B0 + '(?:sumando|revisando|verificando|viendo|revisa|suma)' + B1, 'i'),
];

// --- dinero: la convencion de la casa, `1,234 GYD` --------------------------
const RE_CIFRA = /\d[\d.,]*/g;
const RE_MONEDA_DETRAS = /^\s*\*?\s*(GYD|CUP|USD)\b/i;
const RE_MONEDA_DELANTE = /\b(GYD|CUP|USD)\s*\*?\s*$/i;

function interpretar(bruto) {
  let t = bruto.trim().replace(/[.,]+$/, '');
  if (!t) { return null; }
  if ((t.match(/\./g) || []).length > 1) { return null; }
  const n = Number(t.replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}

function monedaPegada(texto, inicio, fin) {
  let m = RE_MONEDA_DETRAS.exec(texto.slice(fin, fin + 8));
  if (m) { return m[1].toUpperCase(); }
  m = RE_MONEDA_DELANTE.exec(texto.slice(Math.max(0, inicio - 8), inicio));
  return m ? m[1].toUpperCase() : null;
}

function cifrasDe(texto) {
  const salida = [];
  RE_CIFRA.lastIndex = 0;
  let m;
  while ((m = RE_CIFRA.exec(texto || '')) !== null) {
    const bruto = m[0].replace(/[.,]+$/, '');
    if (!bruto) { continue; }
    const inicio = m.index, fin = m.index + bruto.length;
    salida.push({ bruto, inicio, fin,
                  moneda: monedaPegada(texto, inicio, fin),
                  valor: interpretar(bruto) });
  }
  return salida;
}

// --- segmentacion ------------------------------------------------------------
function esCta(t) { return t.includes('?') || RE_CTA_INICIAL.test(t.trim()); }
function tieneHecho(t) { return cifrasDe(t).some(c => c.valor !== null); }
function esAfirmacionDeProceso(t) { return AFIRMACIONES.some(r => r.test(t)); }

function segmentar(texto) {
  const segmentos = [];
  let contador = 0;
  const bloques = (texto || '').split(/\n\s*\n/);
  for (let i = 0; i < bloques.length; i++) {
    for (const linea of bloques[i].split('\n')) {
      if (!linea.trim()) { continue; }
      contador++;
      if (RE_VINETA.test(linea)) {
        segmentos.push({ texto: linea, bloque: i, linea: contador, et: new Set([LIST]) });
        continue;
      }
      for (const frase of linea.split(/(?<=[.!?])\s+/)) {
        if (!frase.trim()) { continue; }
        const et = new Set();
        if (esCta(frase)) { et.add(CTA); }
        if (RE_ACK.test(frase) && !tieneHecho(frase)) { et.add(ACK); }
        if (RE_CLOSING.test(frase)) { et.add(CLOSING); }
        if (tieneHecho(frase)) { et.add(FACTUAL); }
        if (RE_EXPLICATIVO.test(frase)) { et.add(EXPLANATION); }
        if (esAfirmacionDeProceso(frase)) { et.add(PROCESS); }
        if (et.size === 0 || (et.size === 1 && et.has(FACTUAL))) { et.add(ANSWER); }
        segmentos.push({ texto: frase.trim(), bloque: i, linea: contador, et });
      }
    }
  }
  return segmentos;
}

// --- negritas ----------------------------------------------------------------
const COMILLAS = new Set(['"', '“', '”', '«', '»', "'"]);

function entreComillas(texto, pos) {
  let n = 0;
  for (let i = 0; i < pos; i++) { if (COMILLAS.has(texto[i])) { n++; } }
  return n % 2 === 1;
}

function ponerNegritas(texto, autorizados, aplicadas) {
  if (texto.includes('*')) { return [texto, aplicadas]; }
  const partes = [];
  let ultimo = 0, puestas = 0;
  for (const c of cifrasDe(texto)) {
    if (aplicadas + puestas >= MAX_NEGRITAS) { break; }
    if (!c.moneda || c.valor === null) { continue; }
    if (!autorizados.has(redondear(c.valor))) { continue; }
    if (entreComillas(texto, c.inicio)) { continue; }
    let fin = c.fin;
    const m = /^\s*\*?\s*(GYD|CUP|USD)\b/i.exec(texto.slice(fin));
    if (m) { fin += m[0].length; }
    partes.push(texto.slice(ultimo, c.inicio));
    partes.push('*' + texto.slice(c.inicio, fin).trim() + '*');
    ultimo = fin;
    puestas++;
  }
  if (!puestas) { return [texto, aplicadas]; }
  partes.push(texto.slice(ultimo));
  return [partes.join(''), aplicadas + puestas];
}

function redondear(v) { return Math.round(v * 1e6) / 1e6; }
function valores(texto) {
  return cifrasDe(texto).filter(c => c.valor !== null)
    .map(c => redondear(c.valor)).sort((a, b) => a - b);
}

// --- el compilador -----------------------------------------------------------
function compilar(borrador, plan, turno) {
  plan = plan || {};
  turno = turno || {};
  const original = borrador || '';
  if (!original.trim()) { return { texto: original, ops: [], motivo: NO_APPLY }; }

  let segmentos = segmentar(original);
  if (!segmentos.length) { return { texto: original, ops: [], motivo: NO_APPLY }; }

  const ops = [];
  let ctas = segmentos.filter(s => s.et.has(CTA));

  if (ctas.length > 1) {
    const necesarias = ctas.filter(c => c.et.has(FACTUAL) || c.et.has(EXPLANATION) || !c.et.has(ACK));
    const ceremoniales = ctas.filter(c => !necesarias.includes(c));
    if (plan.acknowledgement === 'NONE' && ceremoniales.length) {
      for (const c of ceremoniales) {
        segmentos = segmentos.filter(s => s !== c);
        ops.push(DROP_REDUNDANT_ACK);
      }
      ctas = ctas.filter(c => necesarias.includes(c));
    }
    if (ctas.length > 1) { return { texto: original, ops: [], motivo: HOLD_MULTIPLE_CTA }; }
  }

  if (plan.acknowledgement === 'NONE') {
    for (const s of segmentos.slice()) {
      if (s.et.has(ACK) && !(s.et.has(FACTUAL) || s.et.has(CTA) || s.et.has(ANSWER))) {
        segmentos = segmentos.filter(x => x !== s);
        ops.push(DROP_REDUNDANT_ACK);
      }
    }
  }
  if (plan.verbosityProfile === 'MINIMAL') {
    for (const s of segmentos.slice()) {
      if (s.et.has(CLOSING) && !(s.et.has(FACTUAL) || s.et.has(CTA))) {
        segmentos = segmentos.filter(x => x !== s);
        ops.push(DROP_REDUNDANT_CLOSING);
      }
    }
  }
  if (!segmentos.length) { return { texto: original, ops: [], motivo: NO_APPLY }; }

  if ((plan.format || {}).ctaLast && ctas.length) {
    const cta = ctas[0];
    const i = segmentos.indexOf(cta);
    if (i !== -1 && segmentos[segmentos.length - 1] !== cta) {
      const detras = segmentos.slice(i + 1);
      const seguro = detras.length
        && !detras.some(s => RE_ANAFORA.test(s.texto))
        && !detras.some(s => RE_CONECTOR.test(s.texto));
      if (seguro) {
        segmentos.splice(i, 1);
        segmentos.push(cta);
        ops.push(CTA_MOVE_TO_END);
      }
    }
  }

  // bloques: solo se aisla la pregunta. La estructura de lineas no se toca.
  const bloques = [];
  let grupo = [];
  for (const s of segmentos) {
    if (grupo.length && grupo[0].bloque !== s.bloque) { bloques.push(grupo); grupo = []; }
    grupo.push(s);
  }
  if (grupo.length) { bloques.push(grupo); }

  const finales = [];
  for (const g of bloques) {
    if (g.length > 1 && g[g.length - 1].et.has(CTA)
        && !g.slice(0, -1).some(s => s.et.has(CTA))
        && !RE_CONECTOR.test(g[g.length - 1].texto)) {
      finales.push(g.slice(0, -1));
      finales.push([g[g.length - 1]]);
    } else {
      finales.push(g);
    }
  }

  const autorizados = new Set();
  for (const v of Object.values((turno.facts || {}))) {
    for (const c of cifrasDe(String(v))) {
      if (c.valor !== null) { autorizados.add(redondear(c.valor)); }
    }
  }

  let puestas = Math.floor((original.match(/\*/g) || []).length / 2);
  const textoBloques = [];
  for (const b of finales) {
    const variasLineas = new Set(b.map(x => x.linea)).size > 1;
    const lineas = [];
    for (const s of b) {
      let t = s.texto;
      if (s.et.has(FACTUAL) && autorizados.size && !variasLineas) {
        const r = ponerNegritas(t, autorizados, puestas);
        if (r[0] !== s.texto) { ops.push(APPLY_BOLD_TO_FACT_SPAN); }
        t = r[0]; puestas = r[1];
      }
      lineas.push([t, s]);
    }
    const partes = [];
    let previo = null;
    for (const [t, seg] of lineas) {
      if (previo !== null && seg.linea !== previo) { partes.push('\n'); }
      else if (partes.length) { partes.push(' '); }
      partes.push(t);
      previo = seg.linea;
    }
    textoBloques.push(partes.join(''));
  }
  const compilado = textoBloques.filter(x => x.trim()).join('\n\n');

  const antes = original.split(/\n\s*\n/).map(x => x.trim()).filter(Boolean);
  const despues = textoBloques.map(x => x.trim()).filter(Boolean);
  const fusion = antes.some(a => !despues.includes(a) && despues.some(d => d.includes(a)));
  const corte = despues.some(d => !antes.includes(d) && antes.some(a => a.includes(d)));
  if (corte || despues.length > antes.length) { ops.push(INSERT_PARAGRAPH_BREAK); }
  if (fusion || despues.length < antes.length) { ops.push(REMOVE_PARAGRAPH_BREAK); }

  if (JSON.stringify(valores(compilado)) !== JSON.stringify(valores(original))) {
    return { texto: original, ops: [], motivo: HOLD_UNSUPPORTED };
  }
  if (compilado.trim() === original.trim()) {
    return { texto: original, ops: [], motivo: NO_APPLY };
  }
  return { texto: compilado, ops: [...new Set(ops)].sort(), motivo: 'APPLIED' };
}

// FAIL OPEN: cualquier excepcion devuelve el original.
function compilarSeguro(borrador, plan, turno) {
  try {
    return compilar(borrador, plan, turno);
  } catch (e) {
    return { texto: borrador || '', ops: [], motivo: 'ERROR:' + String(e && e.message).slice(0, 60) };
  }
}

// ---------------------------------------------------------------------------
// CUERPO DEL NODO
// ---------------------------------------------------------------------------
// El plan fijo de produccion: no existe un PRESENTATION_EXTENSION_V2 por turno,
// asi que solo se pide la CTA al final. Con ack NATURAL y perfil NORMAL no se
// quita nada, que es exactamente lo que se valido en los 271 turnos.
const PLAN_PRODUCCION = { turnId: 'prod', primaryGoal: 'ANSWER_QUOTE_AND_ADVANCE',
  acknowledgement: 'NATURAL', verbosityProfile: 'NORMAL', format: { ctaLast: true } };

return $input.all().map(item => {
  const original = item.json && item.json.output;

  let modo = 'off';
  try {
    const b = $('Banderas de optimizacion').first().json || {};
    modo = String((b.banderas || {}).opt_presentation_compiler_v2 || 'off');
  } catch (e) { modo = 'off'; }

  // FAIL OPEN. Si no hay texto, si el modo esta apagado o si algo revienta,
  // sale el ORIGINAL. Esto no puede impedir una respuesta jamas.
  if (modo === 'off' || typeof original !== 'string' || !original.trim()
      || original.trim() === 'SKIP') {
    return { json: { ...item.json, pc_modo: modo, pc_aplicado: false,
                     pc_motivo: 'apagado', pc_ops: [] } };
  }

  const r = compilarSeguro(original, PLAN_PRODUCCION, { facts: { a: original } });
  const aplicado = r.motivo === 'APPLIED';
  const cortes = (r.texto.split(/\n\s*\n/).length) - (original.split(/\n\s*\n/).length);
  const negritas = Math.floor((r.texto.match(/\*/g) || []).length / 2)
                 - Math.floor((original.match(/\*/g) || []).length / 2);

  // En sombra se calcula y se mide, pero SALE EL ORIGINAL.
  const salida = (modo === 'on' && aplicado) ? r.texto : original;

  return { json: { ...item.json, output: salida,
    pc_modo: modo,
    pc_aplicado: modo === 'on' ? aplicado : false,
    pc_candidato_aplicaria: aplicado,
    pc_motivo: r.motivo,
    pc_ops: r.ops,
    pc_cortes: aplicado ? cortes : 0,
    pc_negritas: aplicado ? negritas : 0,
    pc_hold: r.motivo.indexOf('HOLD') === 0 || r.motivo.indexOf('COMPILER_HOLD') === 0
             ? r.motivo : null } };
});

