const crypto = require('crypto');

// El secreto NUNCA vive en el workflow. Variable de entorno de n8n.
const SECRETO = ($env.CEREBRO_WEBHOOK_SECRET || '').toString().trim();
if (!SECRETO) { throw new Error('CEREBRO_WEBHOOK_SECRET no esta configurada en n8n'); }

// Transicion: mientras WaCRM aun mande el secreto por query string se acepta.
// Poner CEREBRO_ACEPTA_QUERY_SECRET=false en cuanto Hermes despliegue la firma.
const LEGACY = ($env.CEREBRO_ACEPTA_QUERY_SECRET || 'true').toString() === 'true';

const req = $input.first().json;
const headers = req.headers || {};
const query = req.query || {};

// Cuerpo CRUDO: la firma se valida sobre los bytes que llegaron, no sobre una
// reserializacion (el orden de claves y los espacios cambiarian el hash).
let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) {
  raw = typeof req.body === 'string' ? req.body : JSON.stringify(req.body ?? {});
}

let body = {};
try { body = JSON.parse(raw || '{}'); } catch (e) { return []; }

const iguales = (a, b) => {
  const A = Buffer.from((a || '').toString(), 'utf8');
  const B = Buffer.from((b || '').toString(), 'utf8');
  if (A.length !== B.length) { return false; }
  return crypto.timingSafeEqual(A, B);
};

const ts  = (headers['x-cerebro-timestamp'] || '').toString();
const sig = (headers['x-cerebro-signature'] || '').toString().replace(/^sha256=/i, '').toLowerCase();

let autorizado = false;
let firma = '';

if (ts && sig) {
  const edad = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
  if (Number.isFinite(edad) && edad <= 300) {
    const esperada = crypto.createHmac('sha256', SECRETO).update(ts + '.' + raw).digest('hex');
    if (iguales(sig, esperada)) { autorizado = true; firma = esperada; }
  }
} else if (LEGACY) {
  if (iguales((query.secret || '').toString(), SECRETO)) { autorizado = true; }
}

if (!autorizado) { return []; }

const d = body.data ?? {};
if (!d.conversation_id) { return []; }

// Reintento automatico: no es un mensaje nuevo del cliente, solo reactiva un lote
// que quedo atascado. No se guarda en session_events.
if (body.event === 'cerebro.reintento') {
  return [{ json: { conversation_id: d.conversation_id, tipo: 'text', texto: '', wamid: '', reintento: true, firma } }];
}
if (body.event !== 'message.received') { return []; }
return [{ json: {
  conversation_id: d.conversation_id,
  tipo: (d.content_type ?? 'text').toString(),
  texto: (d.text ?? '').toString(),
  wamid: (d.whatsapp_message_id ?? '').toString(),
  reintento: false,
  firma
} }];

const eventos = $('Reclamar lote').all().map(i => i.json);
if (!eventos.length) { return []; }
let trans = {};
try {
  const seps = $('Separar audios').all();
  const trs = $('Transcribir audio').all();
  for (let i = 0; i < seps.length; i++) {
    trans[seps[i].json.wamid] = (trs[i]?.json?.text ?? '').toString().trim();
  }
} catch (e) {}
const textos = [];
for (const e of eventos) {
  if (e.tipo === 'text' && (e.contenido ?? '').toString().trim()) {
    textos.push(e.contenido.toString().trim());
  } else if (e.tipo === 'audio') {
    const t = trans[e.whatsapp_message_id];
    if (t) { textos.push('[Nota de voz del cliente]: ' + t); }
    else { textos.push('[El cliente mando una nota de voz que no se pudo transcribir]'); }
  }
}
const imagenes = eventos.filter(e => e.tipo === 'image').map(e => e.whatsapp_message_id).filter(Boolean);
return [{ json: {
  conversation_id: eventos[0].conversation_id,
  telefono: eventos[0].contact_phone,
  n_mensajes: eventos.length,
  texto_completo: textos.join('\n'),
  imagenes,
  eventos
} }];

const crypto = require('crypto');
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'imagen');
  const hash = crypto.createHash('sha256').update(buffer).digest('hex');
  out.push({ json: { ...items[i].json, hash_imagen: hash }, binary: items[i].binary });
}
return out;

// ELIGE ENTRE LAS CUATRO LECTURAS DE LA MISMA IMAGEN (0, 180, 90 y 270 grados)
//
// El orden de decision es el mismo que tenia con dos lecturas:
//   1. Si alguna referencia EXISTE en el libro de depositos, gana esa. Es el
//      arbitro bueno: no opina, comprueba.
//   2. Si ninguna esta en el libro, se puntua la forma (longitud, destinatario,
//      importe, ausencia de alertas).
//   3. Si sigue empatado gana la ORIGINAL, y luego 180, 90 y 270 por ese orden.
//      Sale de medir 60 imagenes reales: la mayoria llegan derechas, luego boca
//      abajo, y de lado es lo mas raro.
//
// Comprobado el 10-ago sobre 9 comprobantes reales: de las lecturas
// equivocadas que producen los giros, NINGUNA existia en el libro, y las
// correctas SI. Anadir candidatos no ensucia la decision.
const prep = $('Preparar candidatos').all();
const libro = $input.all();

// 17-oct: una lectura que NO pasa la verificacion de formato (importe absurdo,
// referencia que no es MMG, tarjeta sin digito de control...) pierde siempre
// frente a una que si la pasa, sea del tipo que sea. Antes un comprobante sin
// referencia le ganaba a un Zelle bien leido (prueba de giros, ids 138/139) y
// un importe de 29 le ganaba al de 29,000 con la misma referencia (id 71).
function puntuar(x) {
  if (!x) { return -3; }
  if (x.verificacion && x.verificacion.ok === false) { return -2; }
  if (x.tipo !== 'comprobante') { return 0; }
  let p = 0;
  const ref = String(x.referencia ?? '').replace(/[^0-9]/g, '');
  if (ref.length === 14) { p += 3; } else if (ref.length >= 10) { p += 1; }
  if (x.destino_correcto === true) { p += 2; }
  if (Number(x.monto) > 0) { p += 1; }
  if ((x.alertas ?? []).length === 0) { p += 1; }
  return p;
}

const out = [];
for (let i = 0; i < prep.length; i++) {
  const p = prep[i].json;
  const ex = libro[i]?.json ?? {};

  // El orden del array ES el orden de preferencia al empatar.
  const cands = [
    { giro: 0,   datos: p.a, ref: p.ref_a, existe: ex.existe_a === true },
    { giro: 180, datos: p.b, ref: p.ref_b, existe: ex.existe_b === true },
    { giro: 90,  datos: p.c, ref: p.ref_c, existe: ex.existe_c === true },
    { giro: 270, datos: p.d, ref: p.ref_d, existe: ex.existe_d === true },
  ].filter((c) => c.datos);

  let elegido = null;
  let arbitro = 'ninguna lectura fue parseable';

  const enLibro = cands.filter((c) => c.existe);
  if (enLibro.length > 0) {
    // sort de V8 es estable: a igual puntuacion manda el orden de preferencia
    const mejor = enLibro.slice().sort((x, y) => puntuar(y.datos) - puntuar(x.datos))[0];
    const refs = new Set(enLibro.map((c) => c.ref));
    elegido = mejor;
    arbitro = refs.size > 1
      ? ('OJO: ' + refs.size + ' referencias distintas existen en el libro; gana el giro ' + mejor.giro)
      : ('la referencia del giro ' + mejor.giro + ' SI esta en el libro');
  } else if (cands.length > 0) {
    let mejor = cands[0];
    for (const c of cands) { if (puntuar(c.datos) > puntuar(mejor.datos)) { mejor = c; } }
    elegido = mejor;
    arbitro = (mejor.giro === cands[0].giro)
      ? 'ninguna esta en el libro: empate o gana la original'
      : ('ninguna esta en el libro: gana por forma el giro ' + mejor.giro);
  }

  let datos = elegido?.datos ?? { tipo: 'otro', descripcion: 'no parseable' };
  const giro = elegido?.giro ?? 0;

  // ---- GUARDA: ¿esto es de verdad un comprobante? -------------------------
  //
  // El 10-ago un cliente mando una CAPTURA DE UN CHAT de WhatsApp en la que se
  // veia el numero de cuenta 6762167. La vision la clasifico como comprobante y
  // leyo ese numero COMO IMPORTE: se creo un deal de 6.762.167 GYD y el bot le
  // dijo al cliente "Recibimos su deposito de 6,762,167 GYD". No habia ningun
  // deposito. Los cuatro giros NO evitan esto: la imagen se leia perfectamente,
  // el problema es que no era un comprobante.
  //
  // Un comprobante de MMG SIEMPRE trae Transaction ID, en los tres formatos.
  // Medido sobre los 26 comprobantes registrados hasta el 10-ago: 25 con
  // referencia de 14 digitos y 1 con 12. NINGUNO legitimo sin referencia. El
