// Junta los candidatos de la imagen. Con la politica B puede haber SOLO la
// primera lectura: las otras tres se leen con try/catch porque su rama puede no
// haberse ejecutado.
//
// LO QUE NO CAMBIA: el orden del array sigue siendo el orden de preferencia al
// empatar (0, 180, 90, 270) y el arbitro sigue siendo `Parsear vision`, que
// pregunta al libro. Aqui solo se prepara lo que hay.
const base = $('Decidir giro').all();
function leer(r) {
  let c = '';
  if (typeof r?.text === 'string') { c = r.text; }
  else if (r?.output) { c = r.output[0]?.content?.[0]?.text ?? ''; }
  else if (r?.choices) { c = r.choices[0]?.message?.content ?? ''; }
  else if (r?.content) { c = typeof r.content === 'string' ? r.content : (r.content[0]?.text ?? ''); }
  const s = String(c).replace(/```json/gi, '').replace(/```/g, '').trim();
