}
const soloDigitos = (x) => String(x ?? '').replace(/[^0-9]/g, '');
const traer = (nombre) => { try { return $(nombre).all(); } catch (e) { return []; } };

const B = traer('Vision segunda lectura (girada)');
const C = traer('Vision tercera lectura (90)');
const D = traer('Vision cuarta lectura (270)');

const out = [];
for (let i = 0; i < base.length; i++) {
  const p = base[i].json;
  const b = p.girar_lote ? verificarLectura(leer(B[i]?.json)) : null;
  const c = p.girar_lote ? verificarLectura(leer(C[i]?.json)) : null;
  const d = p.girar_lote ? verificarLectura(leer(D[i]?.json)) : null;
  out.push({ json: {
    a: p.a, b, c, d,
    ref_a: p.ref_a,
