    vision_calls: p.vision_calls,
    existe_a_1a: p.existe_a,
  } });
}
return out;

// ============================================================================
// FRONTERA DETERMINISTA DE SALIDA — fase 66 (CANDIDATO LOCAL, NO DESPLEGADO)
// ============================================================================
//
// Contrato: fronteraSalida(texto) devuelve SIEMPRE uno de:
//
//   { accion: 'ENVIAR',   texto: <output limpio y formateado> }
//   { accion: 'RECHAZAR', motivo: <slug>, original: <texto original> }
//
// Motivos de RECHAZAR y a qué invariante sirven:
//
//   no_texto              entrada que no es string                (OUT-009/010)
//   vacio                 vacío o solo espacios (tras limpiar)    (OUT-009)
//   skip                  semántica SKIP del Decisor              (OUT-008)
//   dsml_marcado          marcado DSML en cualquiera de sus       (OUT-001)
//                         3 variantes (｜｜ / ｜ / ASCII)
//   dsml_token            la palabra DSML sin marcado — igual de  (OUT-001,
//                         fail-closed que producción hoy           conservador)
//   marcador_interno      [CONTEXTO...], [SISTEMA - ...],         (OUT-002)
//                         "el cliente NO ve esto"
//   razonamiento_ambiguo  huele a razonamiento y no hay corte     (OUT-004)
//                         inequívoco: no se reescribe, se rechaza
//   error_validador       cualquier excepción interna             (OUT-010)
//
// FAIL-CLOSED: ante excepción se RECHAZA, nunca se deja pasar el original.
// (Producción hoy hace lo contrario: el catch devuelve el item intacto.)
//
// NUNCA se reconstruye contenido: o se envía lo que hay (con los saltos del
// normalizador de siempre), o se envía exactamente la respuesta que quedó al
// quitar un razonamiento separable de forma inequívoca, o se rechaza.
// Integridad verificada a la salida: mismos dígitos, mismo contenido
// no-blanco que la base elegida (OUT-005/006/007).
// ----------------------------------------------------------------------------

// --- detección DSML ---------------------------------------------------------
// Las tres variantes reales documentadas en 27-el-dsml-entendido.md:
//   <｜｜DSML｜｜tool_calls>  degradada, la que llega hoy (ejecución 31249)
//   <｜DSML｜tool_calls>     canónica
//   <||DSML||...> / <|DSML|...>  ASCII (reportada por otros clientes)
const RE_DSML_MARCADO = /<\/?\s*(?:｜{1,2}|\|{1,2})\s*DSML\s*(?:｜{1,2}|\|{1,2})/i;
// La palabra suelta, sin marcado. Producción hoy también la rechaza
// (includes('DSML') → throw). Se mantiene el mismo criterio conservador:
// el bot no tiene ninguna razón legítima para decirle "DSML" a un cliente.
const RE_DSML_TOKEN = /DSML/i;

// --- marcadores internos del sistema ----------------------------------------
// El [CONTEXTO DEL SISTEMA - el cliente NO ve esto] viaja en la ENTRADA del
// modelo en cada turno; el riesgo es que lo eco-e en la salida. El
// [SISTEMA - ...] es el marcador de la tubería DSML (fase futura). Ninguno
// puede salir jamás.
const RE_MARCADOR_INTERNO = new RegExp([
  '\\[\\s*CONTEXTO\\b',            // [CONTEXTO DEL SISTEMA...], [CONTEXTO]
  '\\[\\s*SISTEMA\\b',             // [SISTEMA - RESULTADOS...], [SISTEMA]
  'CONTEXTO DEL SISTEMA',          // eco sin corchete
  'el cliente NO ve esto',         // la coletilla del marcador
].join('|'), 'i');

// --- razonamiento -----------------------------------------------------------
// El RE de apertura es EXACTAMENTE el de producción (verificado el 10-ago
// sobre 275 mensajes reales: caza las 4 fugas y ni una más). No se amplía.
const RE_RAZONAMIENTO = /^(el (cliente|usuario)\b|parece que el (cliente|usuario)\b|(no debo|no puedo) (asumir|dar por)|voy a (preguntar|pedir)\b|debo (preguntar|pedir|confirmar)\b)/i;

// --- razonamiento en INGLES (LEGACY OPTIMIZED V1) ---------------------------
// El 18-ago le llego a un cliente entero «The client said "The account" —
// they're asking for the account details... Let me respond in English.» La
// frontera lo dejo pasar: su expresion regular solo miraba el espanol.
//
// El bot SI habla ingles cuando el cliente escribe en ingles, asi que el idioma
// no vale como senal. Lo que no hace nunca un mensaje dirigido al cliente es
// hablar DEL cliente en tercera persona, citar «el contexto» o deliberar en voz
// alta. Eso es lo que se busca aqui, y nada mas: «Alright, let me connect you
// with an operator» es una respuesta legitima y tiene que salir.
const RE_RAZONAMIENTO_EN = /^(the (client|customer|user)\b|wait[,.]|actually,|hmm\b|okay,? so\b|let me (think|check|see|analyze|consider|respond|reply)\b|per the context\b|based on the context\b|looking at the context\b|i (should|need to) (check|confirm|verify|ask|decide|respond|reply)\b)/i;
const RE_SENALES_EN = [
  /\bthe (client|customer|user)\b/i,
  /\bthe context (says|shows|indicates|mentions)\b/i,
  /\b(per|but|from) the context\b/i,
  /\bthey('re| are) asking\b/i,
  /\bi should\b/i,
  /\bi need to (check|confirm|verify|ask|respond|reply)\b/i,
  /\blet me (think|check|see|analyze|respond|reply)\b/i,
];
function senalesEn(bloque) {
  let n = 0;
  for (const re of RE_SENALES_EN) { if (re.test(bloque)) { n++; } }
  return n;
}

// Señales de deliberación DENTRO de un bloque (para el caso de oro del
// 12-ago: razonamiento + respuesta en el mismo párrafo). El corte en el
// mismo bloque exige apertura + al menos UNA señal más: con la apertura
// sola, un "El cliente..." legítimo de una sola pieza se envía tal cual
// (paridad con producción; medido en el corpus: 0 casos así).
const RE_SENALES = [
  /necesito saber/i,
  /le pregunto\b/i,
  /le pido\b/i,
  /no eligi[oó]/i,          // sin \b final: en JS \b no funciona tras vocal acentuada
  /no debo asumir/i,
  /voy a (preguntar|pedir)(le)?\b/i,
  /debo (preguntar|pedir|confirmar)(le)?\b/i,
];

// Un bloque meta consecutivo puede continuar con lo que falta, sin repetir
// «El cliente...» al abrir. Solo cuenta como interno si combina esa apertura
// acotada con un plan explícito de qué preguntarle al cliente.
const RE_CONTINUACION_META = /^(?:pero\s+)?todav[ií]a no (?:me )?ha (?:dado|indicado|confirmado|enviado)\b/i;
const RE_PLAN_INTERNO = /\b(?:necesito|debo|tengo que|voy a) (?:pedir|preguntar|confirmar)(?:le)?\b/i;

function esBloqueMetaEspanol(bloque) {
  return RE_RAZONAMIENTO.test(bloque) ||
    (RE_CONTINUACION_META.test(bloque) && RE_PLAN_INTERNO.test(bloque));
}

// Cierre inequívoco del razonamiento dentro del bloque: la frase-bisagra con
// la que el modelo termina de deliberar y empieza a responder. Solo si existe
// se corta; si no, se RECHAZA (OUT-004: ante ambigüedad, nunca inventar).
const RE_CIERRE_RAZONAMIENTO = /\b(le pregunto|le pido|voy a preguntar(?:le)?|voy a pedir(?:le)?|debo preguntar(?:le)?)\s*[.:]\s+/ig;

// --- normalizador de formato: EL DE PRODUCCIÓN, VERBATIM --------------------
// (copiado byte a byte del nodo actual; no se toca una coma)
function normalizar(txt) {
  if (!txt) return txt;
  if (txt.includes('\n\n')) return txt;   // ya trae PARRAFOS de verdad: no se toca
  const mPreg = txt.match(/^([\s\S]*?)\s+(?:¿[^?]+\?|(?:How|What|When|Where|Which|Can|Could|Would|Do|Did|Are|Is)\b[^?]*\?)\s*$/);
  const preguntaConIdeaDelante = !!(mPreg && mPreg[1].trim().length >= 40);
  if (txt.length < 110 && !preguntaConIdeaDelante) return txt;

  let t = txt.trim();

  t = t.replace(/^((?:Buenos días|Buenas tardes|Buenas noches|Good morning|Good afternoon|Good evening)[^.]*\.)\s+/i, '$1\n\n');

  t = t.replace(/\s+(¿[^?]+\?)\s*$/, '\n\n$1');
  t = t.replace(/(?<=[.!?])\s+((?:How|What|When|Where|Which|Can|Could|Would|Do|Did|Are|Is)\b[^?]*\?)\s*$/, '\n\n$1');

  const bloques = t.split('\n\n');
  if (bloques.length < 3) {
    const i = bloques.length - 1 >= 1 ? bloques.length - 1 : 0;
    const cuerpo = bloques[i];
    if (cuerpo && cuerpo.length > 130) {
      const mitad = Math.floor(cuerpo.length / 2);
      const re = /\.\s+(?=[A-ZÁÉÍÓÚ¿])/g;
      let m, corte = -1;
      while ((m = re.exec(cuerpo)) !== null) {
        if (m.index >= mitad) { corte = m.index + 1; break; }
        corte = m.index + 1;
      }
      if (corte > 0 && corte < cuerpo.length - 20) {
        bloques[i] = cuerpo.slice(0, corte).trim() + '\n\n' + cuerpo.slice(corte).trim();
      }
    }
  }
  t = bloques.join('\n\n');

  const sinEspacios = s => s.replace(/\s+/g, ' ').trim();
  if (sinEspacios(t) !== sinEspacios(txt)) return txt;

  return t.trim();
}

// --- utilidades de integridad ------------------------------------------------
const soloDigitos   = s => (String(s).match(/\d/g) || []).join('');
const sinBlancos    = s => String(s).replace(/\s+/g, '');

function contarSenales(bloque) {
  let n = 0;
  for (const re of RE_SENALES) { if (re.test(bloque)) n++; }
  return n;
}

// Quita el razonamiento. Tres salidas posibles:
//   { texto }                 → base limpia (puede ser la original intacta)
//   { ambiguo: true }         → huele a razonamiento y no hay corte inequívoco
function quitarRazonamientoFrontera(txt) {
  const partes = txt.split(/\n\s*\n/);
  const primera = (partes[0] || '').trim();

  // INGLES primero. Hace falta la apertura O dos senales, y ademas al menos una
  // senal: con una coincidencia debil y suelta no se toca nada.
  const nEn = senalesEn(primera);
  if (RE_RAZONAMIENTO_EN.test(primera) || nEn >= 2) {
    if (nEn >= 1) {
      if (partes.length >= 2) {
        const resto = partes.slice(1).join('\n\n').trim();
        // El resto tiene que estar LIMPIO. Si tambien delibera, no hay respuesta
        // que rescatar y se rechaza (fail-closed, OUT-004: ante ambiguedad, nunca
        // inventar).
        if (resto && senalesEn(resto) === 0 && !RE_RAZONAMIENTO_EN.test(resto)) {
          return { texto: resto };
        }
      }
      return { ambiguo: true };
    }
  }

  if (!esBloqueMetaEspanol(primera)) { return { texto: txt }; }

  // Caso A — razonamiento en uno o más párrafos iniciales separados y respuesta
  // detrás. Cada bloque se vuelve a clasificar; el primer bloque limpio y todo
  // lo que le sigue se conserva EXACTAMENTE (OUT-003).
  if (partes.length >= 2) {
    let primeroLimpio = 0;
    while (primeroLimpio < partes.length &&
           esBloqueMetaEspanol((partes[primeroLimpio] || '').trim())) {
      primeroLimpio++;
    }
    const resto = partes.slice(primeroLimpio).join('\n\n').trim();
    if (resto) { return { texto: resto }; }
    // todos los párrafos eran razonamiento → no hay respuesta que rescatar
    return { ambiguo: true };
  }

  // Caso B — el caso de oro del 12-ago: razonamiento + respuesta en el MISMO
  // bloque. Solo se actúa con la APERTURA (que ya casó) más al menos UNA señal
  // de deliberación; con la apertura sola se envía tal cual (evita falsos
  // positivos de "El cliente..." como sujeto de negocio — fixture familia 9).
  if (contarSenales(primera) < 1) { return { texto: txt }; }

  // Corte inequívoco: la ÚLTIMA frase-bisagra de cierre del razonamiento.
  let m, corte = -1;
  RE_CIERRE_RAZONAMIENTO.lastIndex = 0;
  while ((m = RE_CIERRE_RAZONAMIENTO.exec(primera)) !== null) {
    corte = m.index + m[0].length;
  }
  if (corte > 0) {
    const resto = primera.slice(corte).trim();
    if (resto && !RE_RAZONAMIENTO.test(resto)) { return { texto: resto }; }
  }
  return { ambiguo: true };
}

// --- LA FRONTERA -------------------------------------------------------------
// `hooks` existe solo para los tests (inyectar fallos y probar OUT-010).
// El nodo real no pasa hooks.
function fronteraSalida(texto, hooks) {
  const RECHAZAR = (motivo) => ({ accion: 'RECHAZAR', motivo, original: (typeof texto === 'string' ? texto : null) });
  try {
    if (typeof texto !== 'string') { return RECHAZAR('no_texto'); }
    const original = texto;

    if (!original.trim()) { return RECHAZAR('vacio'); }

    // 1) DSML — fail-closed, antes que nada (OUT-001)
    if (RE_DSML_MARCADO.test(original)) { return RECHAZAR('dsml_marcado'); }
    if (RE_DSML_TOKEN.test(original))   { return RECHAZAR('dsml_token'); }

    // 2) Marcadores internos (OUT-002)
    if (RE_MARCADOR_INTERNO.test(original)) { return RECHAZAR('marcador_interno'); }

    // 3) Razonamiento (OUT-003 / OUT-004)
    const r = (hooks && hooks.quitarRazonamiento ? hooks.quitarRazonamiento : quitarRazonamientoFrontera)(original);
    if (r.ambiguo) { return RECHAZAR('razonamiento_ambiguo'); }
    const base = r.texto;

    // 4) Semántica SKIP sobre el texto YA limpio, como hace producción
    //    (razonamiento + SKIP debe quedar en SKIP) (OUT-008)
    const t = base.trim();
    if (!t) { return RECHAZAR('vacio'); }
    if (t.toUpperCase().startsWith('SKIP')) { return RECHAZAR('skip'); }
    const ultimaLinea = (t.split('\n').pop() || '').trim().toUpperCase();
    if (ultimaLinea === 'SKIP') { return RECHAZAR('skip'); }

    // 5) Formato: el normalizador de producción, sin tocar
    const fmt = (hooks && hooks.normalizar ? hooks.normalizar : normalizar)(t);

    // 6) Integridad de salida (OUT-005/006/007): mismos dígitos y mismo
    //    contenido no-blanco que la base. Si algo no cuadra, la frontera
    //    NO abre: se rechaza.
    if (soloDigitos(fmt) !== soloDigitos(base)) { return RECHAZAR('error_validador'); }
    if (sinBlancos(fmt) !== sinBlancos(base))   { return RECHAZAR('error_validador'); }

    return { accion: 'ENVIAR', texto: fmt };
  } catch (e) {
    // OUT-010: un error del validador JAMÁS abre la frontera.
    return RECHAZAR('error_validador');
  }
}

// --- forma de NODO propuesta (diff, NO desplegado) ---------------------------
// Sustituiría el cuerpo de `Normalizar formato` SIN tocar el cableado:
//   ENVIAR              → { output: texto }            → IF → Responder
//   RECHAZAR skip/vacio → { output: 'SKIP' }           → IF → SKIP - no responder
//                          (silencio deliberado, como hoy)
//   RECHAZAR (resto)    → throw                        → manejador → reintento →
//                          derivación si persiste (mismo camino que el DSML hoy)
// El IF `Respuesta valida?` queda como segunda red, intacto.
/* CUERPO PROPUESTO DEL NODO (referencia para la fase de deploy):
return $input.all().map(item => {
  const r = fronteraSalida(item.json && item.json.output);
  if (r.accion === 'ENVIAR') {
    return { json: { ...item.json, output: r.texto, frontera: 'ENVIAR' } };
  }
  if (r.motivo === 'skip' || r.motivo === 'vacio') {
    return { json: { ...item.json, output: 'SKIP', frontera: r.motivo } };
  }
  throw new Error('Frontera de salida: ' + r.motivo + '; reintentar el lote');
});
*/

if (typeof module !== 'undefined') {
  module.exports = { fronteraSalida, normalizar, quitarRazonamientoFrontera,
                     RE_DSML_MARCADO, RE_DSML_TOKEN, RE_MARCADOR_INTERNO,
                     RE_RAZONAMIENTO };
}


// ==== v2 (fase E) ====
// ============================================================================
// FRONTERA DE SALIDA v2 — CONTRATO ESTRUCTURADO (fase E del plan maestro)
// CANDIDATO LOCAL — NO DESPLEGADO. No sustituye a la v1: la ENVUELVE.
// ============================================================================
//
// La v1 (candidato-frontera-salida.js, DESPLEGADA en `Normalizar formato`
// desde la fase 68) valida TEXTO: DSML, marcadores internos, razonamiento,
// SKIP, vacío, normalización con integridad, fail-closed.
//
// Esta v2 añade lo que pide el plan §7 (Fase E) y la v1 no cubre:
//
//   1. CONTRATO ESTRUCTURADO de salida — siempre devuelve UNA de:
//        { accion:'responder',          texto_cliente, metadata }
//        { accion:'silencio',           metadata }               (SKIP/vacío)
//        { accion:'reintentar',         metadata }               (retry controlado)
//        { accion:'responder_generico', texto_cliente, metadata } (texto fijo seguro)
//        { accion:'derivar_humano',     metadata }
//   2. CAPA 0 sobre el texto crudo: JSON incrustado, XML interno,
//      tool traces y markdown de análisis → RECHAZAR (la v1 no los mira).
//   3. VALIDACIÓN DE SHAPE cuando la salida del LLM ya es JSON/objeto
//      (preparación para salida estructurada futura): solo se admite
//      { accion:'responder', texto_cliente, metadata? }; cualquier campo
//      sensible (reasoning/analysis/scratchpad/…) o inesperado → RECHAZAR.
//   4. POLÍTICA DE FALLBACK explícita y por contexto (§ decidirFallback):
//      nunca improvisar, nunca dejar pasar el original.
//
// PRINCIPIOS HEREDADOS DE LA v1 (sin excepción):
//   - FAIL-CLOSED: toda excepción interna → rechazo, jamás pasa el original.
//   - NUNCA reconstruir contenido.
//   - metadata NUNCA lleva el texto original ni razonamiento: solo motivo,
//     capa, sha256 corto y longitud (auditable sin persistir contenido).
// ----------------------------------------------------------------------------
'use strict';
const crypto = require('crypto');


// --- CAPA 0: detectores nuevos sobre texto crudo ----------------------------
// XML interno: etiquetas de deliberación/herramientas. Lista explícita, no un
// genérico <.*>: un cliente legítimo jamás recibe estas etiquetas, y un
// genérico daría falsos positivos (p. ej. "<3").
const RE_XML_INTERNO = /<\/?\s*(think(?:ing)?|analysis|reasoning|reflection|scratchpad|plan|inner[_-]?monologue|tool[_-]?calls?|function[_-]?call|invoke|antml[:a-z_]*|system|internal)\b/i;

// Tool traces: nombres reales de las 11 tools del Cerebro usados como llamada,
// o restos de estructura de tool-calling.
const RE_TOOL_TRACE = new RegExp([
  '\\b(?:consultar_tasas|consultar_servicio|calcular_envio|calcular_inverso|calcular_usd|calcular_usd_desde_gyd|derivar_humano|gestionar_beneficiario|marcar_destino_usd|registrar_beneficiario_zelle|registrar_reparto_multiple)\\s*\\(',
  '"(?:tool_calls?|function_call|tool_call_id)"',
  '\\btool_calls?\\s*[:=]',
].join('|'), 'i');

// Markdown de análisis: encabezados o negritas de deliberación.
const RE_MD_ANALISIS = /(^|\n)\s*(?:#{1,6}\s*|\*\*)\s*(an[aá]lisis|razonamiento|pensamiento|reasoning|analysis|thinking|scratchpad|plan de acci[oó]n)\b/i;

// JSON incrustado: un objeto JSON dentro de texto conversacional.
const RE_JSON_INCRUSTADO = /\{\s*"[^"]+"\s*:/;

// Campos sensibles que JAMÁS se aceptan en una salida estructurada.
const CAMPOS_SENSIBLES = new Set([
  'reasoning', 'razonamiento', 'analysis', 'analisis', 'análisis',
  'scratchpad', 'thinking', 'thought', 'thoughts', 'chain_of_thought', 'cot',
  'tool_calls', 'tool_call', 'tool_trace', 'tool_traces', 'function_call',
  'internal', 'interno', 'prompt', 'system', 'system_prompt', 'debug',
]);
const CAMPOS_PERMITIDOS = new Set(['accion', 'texto_cliente', 'metadata']);

// Texto fijo del fallback genérico. REDACCIÓN PENDIENTE DE PRODUCTO: el
// contenido exacto lo aprueba Humberto/Codex antes de cualquier deploy.
const TEXTO_GENERICO =
  'Disculpe, tuve un problema para procesar su mensaje. ¿Me lo repite, por favor?';

// ----------------------------------------------------------------------------
const hash16 = s => crypto.createHash('sha256').update(String(s)).digest('hex').slice(0, 16);

function metadataDe(motivo, capa, original, extra) {
  return Object.assign({
    motivo, capa,
    sha256_original: hash16(original == null ? '' : original),
    longitud_original: original == null ? 0 : String(original).length,
  }, extra || {});
}

// --- validación de shape (salida estructurada del LLM) ----------------------
// Devuelve { texto } si el objeto cumple el contrato, o { motivo } si no.
function validarShape(obj) {
  if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) {
    return { motivo: 'shape_invalido' };
  }
  const claves = Object.keys(obj);
  for (const k of claves) {
    if (CAMPOS_SENSIBLES.has(k.toLowerCase())) return { motivo: 'campo_sensible' };
    if (!CAMPOS_PERMITIDOS.has(k)) return { motivo: 'shape_invalido' };
  }
  if (obj.accion !== 'responder') return { motivo: 'shape_invalido' };
  if (typeof obj.texto_cliente !== 'string' || !obj.texto_cliente.trim()) {
    return { motivo: 'vacio' };
  }
  if ('metadata' in obj) {
    const m = obj.metadata;
    if (typeof m !== 'object' || m === null || Array.isArray(m)) {
      return { motivo: 'shape_invalido' };
    }
    for (const k of Object.keys(m)) {
      if (CAMPOS_SENSIBLES.has(k.toLowerCase())) return { motivo: 'campo_sensible' };
    }
  }
  return { texto: obj.texto_cliente };
}

// --- capa 0 sobre texto crudo -----------------------------------------------
function capa0(texto, det) {
  if (det.xml.test(texto)) return 'xml_interno';
  if (det.tool.test(texto)) return 'tool_trace';
  if (det.md.test(texto)) return 'markdown_analisis';
  if (det.json.test(texto)) return 'json_interno';
  return null;
}

// --- política de fallback (por contexto, nunca improvisa) --------------------
// contexto: { intentos_previos: n, operacion_financiera: bool,
//             permite_reintento: bool }
// Silencio deliberado solo para skip/vacío (paridad con producción hoy).
// Motivo grave: 1º reintento controlado; si ya se reintentó,
//   con operación financiera abierta → derivar a humano,
//   sin ella → respuesta genérica fija (jamás el original).
function decidirFallback(motivo, contexto) {
  const ctx = Object.assign(
    { intentos_previos: 0, operacion_financiera: false, permite_reintento: true },
    contexto || {});
  if (motivo === 'skip' || motivo === 'vacio') return { accion: 'silencio' };
  if (ctx.permite_reintento && ctx.intentos_previos < 1) return { accion: 'reintentar' };
  if (ctx.operacion_financiera) return { accion: 'derivar_humano' };
  return { accion: 'responder_generico' };
}

// --- LA FRONTERA v2 ----------------------------------------------------------
// salida: lo que produjo el LLM (string, u objeto ya parseado).
// contexto: ver decidirFallback.
// hooks: SOLO para sabotajes del banco (nunca en producción).
function fronteraSalidaV2(salida, contexto, hooks) {
  const H = hooks || {};
  const det = {
    xml: H.xml || RE_XML_INTERNO, tool: H.tool || RE_TOOL_TRACE,
    md: H.md || RE_MD_ANALISIS, json: H.json || RE_JSON_INCRUSTADO,
  };
  const validar = H.validarShape || validarShape;
  const v1 = H.fronteraV1 || fronteraSalida;

  const RECHAZO = (motivo, capa, original) => {
    const f = decidirFallback(motivo, contexto);
    const out = { accion: f.accion, metadata: metadataDe(motivo, capa, original) };
    if (f.accion === 'responder_generico') out.texto_cliente = TEXTO_GENERICO;
    return out;
  };

  try {
    let texto = salida;
    let capaShape = false;

    // ¿Salida estructurada? (objeto directo, o string que ES un JSON completo)
    if (typeof salida === 'object' && salida !== null) {
      capaShape = true;
    } else if (typeof salida === 'string' && /^\s*\{[\s\S]*\}\s*$/.test(salida)) {
      try { salida = JSON.parse(salida); capaShape = true; }
      catch (e) { return RECHAZO('json_malformado', 'shape', texto); }
    }
    if (capaShape) {
      const r = validar(salida);
      if (r.motivo) return RECHAZO(r.motivo, 'shape', JSON.stringify(salida));
      texto = r.texto;
    }

    if (typeof texto !== 'string') return RECHAZO('no_texto', 'shape', '');

    // CAPA 0: contaminación estructural en el texto
    const c0 = capa0(texto, det);
    if (c0) return RECHAZO(c0, 'capa0', texto);

    // CAPA 1: la frontera v1 desplegada, tal cual (DSML, marcadores,
    // razonamiento, SKIP, vacío, normalización + integridad, fail-closed)
    const r1 = v1(texto);
    if (r1.accion === 'RECHAZAR') return RECHAZO(r1.motivo, 'v1', texto);

    return {
      accion: 'responder',
      texto_cliente: r1.texto,
      metadata: metadataDe('ok', capaShape ? 'shape+v1' : 'v1', texto),
    };
  } catch (e) {
    // FAIL-CLOSED heredado: un error del validador JAMÁS abre la frontera.
    return RECHAZO('error_validador', 'v2', typeof salida === 'string' ? salida : '');
  }
}


// ==== CUERPO DEL NODO (fase E) — wrapper v2 de producción ====
// Contexto: `reintento` viene del marcador que Validar evento ya emite
// (evento cerebro.reintento del manejador). Fail-safe: si no se puede leer,
// se asume primer intento (comportamiento v1: throw → manejador).
// `operacion_financiera` queda en false: la rama derivar_humano permanece
// dormida hasta que exista señal fiable (decisión documentada en el deploy).
return $input.all().map(item => {
  let reintento = false;
  try { reintento = $('Validar evento').first().json.reintento === true; } catch (e) {}
  const contexto = { intentos_previos: reintento ? 1 : 0,
                     operacion_financiera: false, permite_reintento: true };
  const r = fronteraSalidaV2(item.json && item.json.output, contexto);
  if (r.accion === 'responder' || r.accion === 'responder_generico') {
    return { json: { ...item.json, output: r.texto_cliente,
                     frontera: r.accion, frontera_motivo: r.metadata.motivo } };
  }
  if (r.accion === 'silencio' || r.accion === 'derivar_humano') {
    return { json: { ...item.json, output: 'SKIP',
                     frontera: r.accion, frontera_motivo: r.metadata.motivo } };
  }
  // reintentar: MISMO gancho del manejador que la v1 (estado error)
  throw new Error('Frontera de salida v2: ' + r.metadata.motivo + '; reintentar el lote');
});

// El nodo de vision no deja pasar la imagen, solo su respuesta. Aqui se vuelve
// a coger el binario original de 'Hash imagen', por posicion.
